/**
 * Inline SVG for a named icon.
 * @param {string} name   Material Symbol name, e.g. 'mic'
 * @param {object} [opts]
 * @param {boolean} [opts.fill]   force the filled (true) or outline (false) glyph
 * @param {string}  [opts.size]   'sm' (20px) | 'lg' (32px); default 24px
 * @param {string}  [opts.label]  accessible name; without it the icon is decorative (aria-hidden)
 * @param {string}  [opts.className] extra classes
 * Unknown names return '' (and warn) rather than throwing in the middle of a render.
 */
FP.icon = function (name, opts) {
  var def = FP.ICONS[name];
  if (!def) {
    if (typeof console !== 'undefined') console.warn('[FluentPath] Unknown icon: ' + name);
    return '';
  }
  opts = opts || {};
  var filled = opts.fill === undefined ? !!def[0] : !!opts.fill;
  var cls = 'fp-icon' + (opts.size ? ' fp-icon--' + opts.size : '') + (opts.className ? ' ' + opts.className : '');
  var a11y = opts.label
    ? 'role="img" aria-label="' + String(opts.label).replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;') + '"'
    : 'aria-hidden="true" focusable="false"';
  return '<svg class="' + cls + '" viewBox="0 -960 960 960" ' + a11y + '><path d="' + (filled ? def[2] : def[1]) + '"/></svg>';
};

/**
 * Replace every <i data-icon="mic" data-icon-size="sm" data-icon-fill="true"
 * data-icon-label="Record"> placeholder under `root` with its SVG. Runs once on
 * DOMContentLoaded; call it again after inserting placeholders dynamically.
 */
FP.hydrateIcons = function (root) {
  (root || document).querySelectorAll('[data-icon]').forEach(function (el) {
    var fillAttr = el.getAttribute('data-icon-fill');
    var svg = FP.icon(el.getAttribute('data-icon'), {
      fill: fillAttr === null ? undefined : fillAttr !== 'false',
      size: el.getAttribute('data-icon-size') || undefined,
      label: el.getAttribute('data-icon-label') || undefined,
      className: el.getAttribute('data-icon-class') || undefined,
    });
    if (svg) el.outerHTML = svg;
  });
};
if (typeof document !== 'undefined') {
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', function () { FP.hydrateIcons(); });
  else FP.hydrateIcons();
}
